import{_ as e,o as a,c as r,a0 as d}from"./chunks/framework.DQOulFGV.js";const b=JSON.parse('{"title":"Keelhaven 和同类工具","description":"Keelhaven 与时间机器、Arq、Backblaze 电脑备份、restic 命令行、Backrest、Vorta 的对比，以及备份 Mac 时它们各自什么时候更合适。","frontmatter":{"title":"Keelhaven 和同类工具","description":"Keelhaven 与时间机器、Arq、Backblaze 电脑备份、restic 命令行、Backrest、Vorta 的对比，以及备份 Mac 时它们各自什么时候更合适。"},"headers":[],"relativePath":"zh/compare.md","filePath":"zh/compare.md"}'),o={name:"zh/compare.md"};function n(c,t,h,s,l,i){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="keelhaven-和同类工具" tabindex="-1">Keelhaven 和同类工具 <a class="header-anchor" href="#keelhaven-和同类工具" aria-label="Permalink to &quot;Keelhaven 和同类工具&quot;">​</a></h1><p>Keelhaven 只做一件事：把你选的文件夹加密后，存一份到你自己的存储上。 好几个不错的工具和它有重叠，其中有的可能更适合你。</p><table tabindex="0"><thead><tr><th></th><th>价格</th><th>开源</th><th>存到哪</th><th>形态</th></tr></thead><tbody><tr><td><strong>Keelhaven</strong></td><td>免费</td><td>是</td><td>你的硬盘、存储桶或服务器</td><td>Mac 菜单栏应用</td></tr><tr><td><strong>时间机器</strong></td><td>macOS 自带</td><td>否</td><td>硬盘或网络磁盘</td><td>macOS 的一部分</td></tr><tr><td><strong>Arq</strong></td><td>付费授权</td><td>否</td><td>你的硬盘、服务器或网盘账号</td><td>Mac 和 Windows 应用</td></tr><tr><td><strong>Backblaze 电脑备份</strong></td><td>订阅</td><td>否</td><td>Backblaze</td><td>Mac 和 Windows 应用</td></tr><tr><td><strong>restic</strong></td><td>免费</td><td>是</td><td>你的硬盘、存储桶或服务器</td><td>命令行</td></tr><tr><td><strong>Backrest</strong></td><td>免费</td><td>是</td><td>restic 能连的任何地方</td><td>本机提供的网页界面</td></tr><tr><td><strong>Vorta</strong></td><td>免费</td><td>是</td><td>硬盘，或装了 Borg 的服务器</td><td>Mac 和 Linux 应用</td></tr></tbody></table><h2 id="时间机器" tabindex="-1">时间机器 <a class="header-anchor" href="#时间机器" aria-label="Permalink to &quot;时间机器&quot;">​</a></h2><p>两个一起用。时间机器擅长把整台 Mac 恢复原样，用的是桌上那块硬盘。 Keelhaven 管的是第二份副本：丢不起的那些文件夹，加密后放到别的地方。</p><h2 id="arq" tabindex="-1">Arq <a class="header-anchor" href="#arq" aria-label="Permalink to &quot;Arq&quot;">​</a></h2><p>思路最接近的一个：你的文件、你的存储、你的密钥。Arq 做得更久，也支持 Windows，还能备份到 Google Drive、OneDrive 和 Dropbox。</p><p>想要免费、开源，备份格式别的工具也能读，就选 Keelhaven。</p><h2 id="backblaze-电脑备份" tabindex="-1">Backblaze 电脑备份 <a class="header-anchor" href="#backblaze-电脑备份" aria-label="Permalink to &quot;Backblaze 电脑备份&quot;">​</a></h2><p>最省事的方案：一份订阅，整台电脑，存在他们那里。宁愿花钱把这件事整个 交出去，就选它。</p><p>想自己决定数据放哪，或者手里已经有 NAS、有存储桶，就选 Keelhaven。</p><h2 id="restic" tabindex="-1">restic <a class="header-anchor" href="#restic" aria-label="Permalink to &quot;restic&quot;">​</a></h2><p>restic 是 Keelhaven 的引擎。如果一个 launchd 任务加上脚本里的密码就够你用， 那你不需要 Keelhaven。</p><p>它补上的是命令行工具留给你自己操心的部分：定时真的会跑，密钥放钥匙串， 出了问题会通知你。仓库仍然是原样的 restic 仓库，见 <a href="/zh/restic">写给 restic 用户</a>。</p><h2 id="backrest" tabindex="-1">Backrest <a class="header-anchor" href="#backrest" aria-label="Permalink to &quot;Backrest&quot;">​</a></h2><p>同样是 restic 的前端，在浏览器里用。除了 Mac，它还能跑在 Linux、Docker 和 NAS 上，开放的 restic 功能也比 Keelhaven 多。给服务器用，或者每个参数 都想自己调，就选它。</p><p>一台不想操心的 Mac，就选 Keelhaven：原生应用，不用开浏览器，默认值已经是 对的。</p><h2 id="vorta" tabindex="-1">Vorta <a class="header-anchor" href="#vorta" aria-label="Permalink to &quot;Vorta&quot;">​</a></h2><p>和 Keelhaven 一样是桌面应用，引擎是 BorgBackup 而不是 restic。Borg 要的是 一块硬盘，或者一台能运行它的服务器，而不是一个普通的存储桶。已经在用 Borg 的话，就选它。</p>',19)])])}const k=e(o,[["render",n]]);export{b as __pageData,k as default};
